insert into rubrics (id, exam_board_id, type, definition) values ('fumarc_redacao', 'fumarc', 'general_essay', '{"criteria": [{"id": "AI", "name": "Argumentação e informatividade", "max": 15, "bands": {"poor": [0, 4], "fair": [5, 8], "good": [9, 12], "very_good": [13, 15]}}, {"id": "CC", "name": "Coerência e coesão", "max": 15, "bands": {"poor": [0, 4], "fair": [5, 8], "good": [9, 12], "very_good": [13, 15]}}, {"id": "M", "name": "Morfossintaxe", "max": 10, "deduction_per_error": 1}, {"id": "PO", "name": "Pontuação, acentuação e ortografia", "max": 10, "deduction_per_error": 1}], "zeroed_if": ["menos de 20 linhas", "fuga ao conteúdo", "letra ilegível", "lápis", "identificação indevida"]}'::jsonb) on conflict (id) do update set definition = excluded.definition;
insert into rubrics (id, exam_board_id, type, definition) values ('fcc_redacao', 'fcc', 'general_essay', '{"criteria": [{"id": "recorte", "name": "Recorte temático", "max": 2}, {"id": "textos_apoio", "name": "Interpretação crítica dos textos de apoio", "max": 2}, {"id": "progressao", "name": "Progressão textual", "max": 3}, {"id": "vocabulario", "name": "Propriedade vocabular", "max": 0.8}, {"id": "coesao", "name": "Coesão textual", "max": 1.6}, {"id": "morfossintaxe", "name": "Morfossintaxe", "max": 0.6}], "zeroed_if": ["fuga ao tema ou ao gênero", "até 7 linhas", "identificação", "cópia de modelos prontos"]}'::jsonb) on conflict (id) do update set definition = excluded.definition;
insert into rubrics (id, exam_board_id, type, definition) values ('ibfc_estudo_caso', 'ibfc', 'technical_case_study', '{"criteria": [{"id": "estrutura", "name": "Estrutura dissertativo-argumentativa", "max": 10}, {"id": "conteudo", "name": "Conteúdo: fidelidade ao tema, argumentação, senso crítico", "max": 20}, {"id": "expressao", "name": "Expressão: norma culta, clareza, coesão", "max": 10}], "zeroed_if": ["nota zero em qualquer critério elimina"]}'::jsonb) on conflict (id) do update set definition = excluded.definition;
insert into rubrics (id, exam_board_id, type, definition) values ('cebraspe_redacao', 'cebraspe', 'general_essay', '{"formula": "NPD = NC - 4 * NE / TL", "NC_max": 20, "legend": {"NC": "nota de conteúdo", "NE": "número de erros de língua", "TL": "linhas escritas"}, "technical_variant": {"usage": "questão dissertativa técnica de até 45 linhas (cargos específicos)", "formula": "NPD = NC - 6 * NE / TL", "NC_max": 30}}'::jsonb) on conflict (id) do update set definition = excluded.definition;
insert into rubrics (id, exam_board_id, type, definition) values ('vunesp_tjsp_discursiva', 'vunesp', 'technical_questions_and_case_study', '{"criteria": [{"id": "questao", "name": "Questão dissertativa (cada uma das 6)", "max": 0.36, "quantity": 6}, {"id": "estudo_caso", "name": "Estudo de caso", "max": 0.84, "quantity": 1}], "assessed_aspects": ["conhecimento e capacidade teórico-prática", "organização do texto", "análise e síntese dos fatos", "correção gramatical", "raciocínio", "fundamentação e consistência", "interpretação e exposição"], "zeroed_if": ["resposta inadequada ao caso proposto", "identificação do candidato", "uso de corretor ou marca-texto", "em branco", "texto não articulado verbalmente ou fora da língua portuguesa", "letra ilegível", "texto definitivo fora do espaço reservado", "cópia do texto base ou fatos estranhos à proposta"]}'::jsonb) on conflict (id) do update set definition = excluded.definition;
insert into rubrics (id, exam_board_id, type, definition) values ('fgv_tjrj_discursiva', 'fgv', 'technical_question', '{"criteria": [{"id": "questao", "name": "Questão discursiva", "max": 20}], "assessed_aspects": ["acerto das respostas", "grau de conhecimento do tema", "fluência e coerência da exposição"], "zeroed_if": ["escrita a lápis", "em branco", "letra ilegível"], "eliminated_if": ["identificação do candidato na folha definitiva", "não devolver a folha de textos definitivos"]}'::jsonb) on conflict (id) do update set definition = excluded.definition;
insert into rubrics (id, exam_board_id, type, definition) values ('aocp_trf2_estudo_caso', 'aocp', 'technical_case_study', '{"per": "question", "questions": 3, "criteria": [{"id": "conhecimento_tecnico", "name": "Conhecimento técnico sobre a matéria", "max": 6}, {"id": "argumentacao", "name": "Clareza na argumentação e senso crítico", "max": 2}, {"id": "lingua", "name": "Língua Portuguesa, clareza e coerência", "max": 2}], "passing_rule": "50% ou mais em cada estudo de caso, nenhum aspecto com nota zero e 60% ou mais do total", "line_limit": 15}'::jsonb) on conflict (id) do update set definition = excluded.definition;
insert into rubrics (id, exam_board_id, type, definition) values ('fcc_estudo_caso', 'fcc', 'technical_case_study', '{"criteria": [{"id": "questao", "name": "Questão prática (cada uma)", "max": 10}], "assessed_aspects": ["domínio do conteúdo dos temas abordados", "experiência prévia e adequação às atribuições do cargo", "correção gramatical", "atendimento à grade de correção da banca"], "penalized_if": ["abordagem tangencial, parcial ou diluída em divagações", "cópia de textos ou de questões da prova", "texto além do limite de linhas"], "zeroed_if": ["fuga ao tema", "texto não articulado verbalmente ou fora do local apropriado", "identificação do candidato", "em branco", "letra ilegível", "não atender aos requisitos da grade de correção"]}'::jsonb) on conflict (id) do update set definition = excluded.definition;
